def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    days, seconds, microseconds = divmod(nanoseconds, 86400000000)
    return datetime.fromtimestamp((days * 24 + seconds) / 60.0, tz=tz)

def dehydrate_timedelta(value):
    """
    Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    days, remainder = divmod(value.days, 1)
    hours, remainder = divmod(remainder, 1)
    minutes, seconds = divmod(remainder, 1)
    if days == 0:
        if hours == 0:
            if minutes == 0:
                if seconds == 0:
                    return "0s"
                return "%ds" % seconds
            else:
                return "%dm%ds" % (minutes, seconds)
        else:
            if minutes == 0:
                return "%dh%ds" % (hours, seconds)
            else:
                return "%dh%dm%ds" % (hours, minutes, seconds)
    else:
        return "%dd%dh%dm%ds" % (days, hours, minutes, seconds)

