def get_versions():
    """Get version information or return default if unable to do so."""
    versions = {}

    # Try to get version information from setup.py
    try:
        with open('setup.py', 'r') as read_file:
            lines = read_file.readlines()
            for line in lines:
                if 'version' in line:
                    match = re.search(r'^\s*version\s*=\s*"([^"]+)"', line)
                    if match:
                        versions['setup.py'] = match.group(1)
                        break
                elif 'version=' in line:
                    match = re.search(r'^\s*version\s*=\s*([0-9.]+)', line)
                    if match:
                        versions['setup.py'] = match.group(1)
                        break
    except IOError:
        pass

    # Try to get version information from requirements.txt
    try:
        with open('requirements.txt', 'r') as read_file:
            for line in read_file:
                if '^-e' not in line and '==' in line:
                    package_name, version = line.split('==')
                    versions[package_name] = version
    except IOError:
        pass

    # Check the 'environment_variables' directory for environment variable version information
    if os.path.exists('environment_variables'):
        version_file = os.path.join('environment_variables', 'VERSION')
        if os.path.isfile(version_file):
            with open(version_file, 'r') as read_file:
                versions['environment_variables/VERSION'] = read_file.read().strip()

    for _, package in pkg_resources.working_set:
        version = package.VERSION
        versions[package.project_name] = version

    return versions

