def subclasses(cls):
    """Return all subclasses of a class, recursively"""

    def recurse(cls):
        """Helper function for recursion."""
        seen = set()
        queue = set([cls,].extend(cls.__subclasses__()))

        while queue:
            c = queue.pop()
            seen.add(c)

            sc = c.__subclasses__()
            queue.extend(sc)

        return seen

    return recurse(cls)

