def string_to_int(string: str, alphabet: List[str]) -> int:
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    base = len(alphabet)
    inverse_alphabet = dict(zip(alphabet, range(0, base)))
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    exp = len(string) - 1
    res = 0
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' is not in the alphabet.")
        res += inverse_alphabet[char] * (base ** exp)
        exp -= 1
    return res

