        """Remove and return the `(key, value)` pair least frequently used."""
        if not self._redis:
            raise KeyError('the dictionary is empty')
        if len(self._redis) == 1:
            key, value = next(iter(self._redis.items()))
            self._remove((key, value))
            return (key, value)

        # Find the item with the least count
        least_frequent = self._find_lt(10000)  # Arbitrarily large initial value
        for key, count in self._count.items():
            least_frequent = min(least_frequent, key, count)
        key, value = least_frequent
        self._remove((key, value))
