def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
       """
    parser = getattr(self, parser_name)
    if parser_name == 'main':
        parser.add_argument('--log-level',
                            help='Set the logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL)',
                            type=str)
        parser.add_argument('--log-path',
                            help='Set the logging path (default: std.out)',
                            type=str)

    # Convert values_dict to specified types based on argument types
    for key, value in values_dict.items():
        arg_info = parser.get_option(key)
        if arg_info and arg_info.nargs == 0:
            # Handle single argument
            if arg_info.type == str:
                if arg_info.choices:
                    values_dict[key] = arg_info.choices[0]
                elif arg_info.nargs == 1:
                    values_dict[key] = str(value)
            elif arg_info.type == int:
                try:
                    values_dict[key] = int(value)
                except ValueError:
                    value = arg_info.type(arg_info.default)
                    values_dict[key] = value
            elif arg_info.type == float:
                try:
                    values_dict[key] = float(value)
                except ValueError:
                    value = arg_info.type(arg_info.default)
                    values_dict[key] = value
        elif arg_info and arg_info.nargs > 0:
            # Handle multiple arguments
            if arg_info.type == bool:
                values_dict[key] = bool(value)
            elif arg_info.type == list:
                if arg_info.nargs == 1:
                    values_dict[key] = [str(value)]
                else:
                    values_dict[key] = [int(value) if arg_info.type == int else float(value) for value in value.split()]
            elif arg_info.type == dict:
                if arg_info.nargs == 1:
                    values_dict[key] = {str(value): str(value)}
                else:
                    values_dict[key] = {int(value): int(value) if arg_info.type == int else float(value) for value in value.split()}

    return values_dict

